(function(root){
function value(principal,rate,years,type='compound',frequency=1){if(![principal,rate,years,frequency].every(Number.isFinite)||principal<=0||years<0||frequency<=0)throw new RangeError('Invalid investment inputs');const r=rate/100;if(type==='simple')return principal*(1+r*years);if(1+r/frequency<=0)throw new RangeError('Rate makes the compounding base non-positive');return principal*Math.pow(1+r/frequency,frequency*years)}
function requiredRate(principal,profit,years,type='compound',frequency=1){if(![principal,profit,years,frequency].every(Number.isFinite)||principal<=0||years<=0||principal+profit<=0||frequency<=0)throw new RangeError('Invalid target inputs');return type==='simple'?100*profit/principal/years:100*frequency*Math.expm1(Math.log1p(profit/principal)/(frequency*years))}
function schedule(m){const rate=m.solve==='profit'?m.rate:requiredRate(m.principal,m.profit,m.years,m.type,m.frequency);return {rate,rows:Array.from({length:m.years+1},(_,year)=>{const balance=value(m.principal,rate,year,m.type,m.frequency);return {year,balance,profit:balance-m.principal}})}}
const api={value,requiredRate,schedule};root.InvestmentMath=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
let mathModel=null;
function seedMath(){mathModel={principal:state.amount,years:state.term,rate:state.rate,profit:Math.max(0,state.target-state.amount),type:'compound',frequency:1,solve:'profit',inspect:state.term}}
function mathInput(key,label,min,max,step,prefix=''){return `<label class="field math-field">${label}<div class="math-number"><span>${prefix}</span><input data-math="${key}" name="${key}" aria-label="${label}" type="number" min="${min}" max="${max}" step="${step}" value="${mathModel[key]}" required></div><input type="range" aria-label="${label} slider" data-math-range="${key}" min="${min}" max="${max}" step="${step}" value="${mathModel[key]}"></label>`}
function scenarios(){if(!mathModel)seedMath();return title('03 / EXPLORE','See your money grow. Step by step.','Adjust the numbers. Watch the mathematics change.',btn('Replay the past','history',false))+`<div class="math-layout"><section class="panel math-controls"><div class="panel-head"><h2>Build your example</h2><button class="math-reset" id="math-reset">Reset from plan ↶</button></div><label class="field">What would you like to calculate?<select id="math-solve"><option value="profit" ${mathModel.solve==='profit'?'selected':''}>Profit from an interest rate</option><option value="rate" ${mathModel.solve==='rate'?'selected':''}>Interest rate needed for a target profit</option></select></label><div class="math-inputs">${mathInput('principal','Principal (₹)',1,10000000,1,'₹')}${mathInput('years','Tenure (years)',1,30,1)}${mathModel.solve==='profit'?mathInput('rate','Annual interest rate (%)',0,Math.max(50,Math.ceil(mathModel.rate)),.01,'%'):mathInput('profit','Target profit (₹)',0,Math.max(10000000,Math.ceil(mathModel.profit)),.01,'₹')}</div><label class="field">Interest calculation<select id="math-type"><option value="compound" ${mathModel.type==='compound'?'selected':''}>Compound interest</option><option value="simple" ${mathModel.type==='simple'?'selected':''}>Simple interest</option></select></label>${mathModel.type==='compound'?`<label class="field" style="margin-top:18px">Compounding frequency<select id="math-frequency">${[[1,'Annually'],[4,'Quarterly'],[12,'Monthly']].map(([n,l])=>`<option value="${n}" ${mathModel.frequency===n?'selected':''}>${l}</option>`).join('')}</select></label>`:''}<div id="math-error" role="alert" class="math-error"></div><p class="small" style="margin-top:18px">Explore freely. These calculator inputs do not change your saved client plan or product rules.</p></section><div id="math-results" aria-live="polite">${mathResults()}</div></div><details class="panel product-detail" open><summary>Market-linked product scenarios <span>Current saved plan · ${money(state.amount)} · ${state.term} years</span></summary><div class="product-detail-body">${productScenarios()}</div></details>`}
function mathResults(){const m=mathModel,{rate,rows}=InvestmentMath.schedule(m),last=rows.at(-1),selected=rows[Math.min(m.inspect,m.years)],earned=last.profit;const simple=InvestmentMath.value(m.principal,rate,m.years,'simple');const freq={1:'annual',4:'quarterly',12:'monthly'}[m.frequency];return `<div class="math-stats">${card('At the end of '+m.years+' years',money(last.balance),'Principal + calculated profit')}${card('Total profit',money(earned),((earned/m.principal)*100).toFixed(2)+'% total return')}${card(m.solve==='rate'?'Required annual rate':'Annual interest rate',rate.toFixed(3)+'%',m.type==='compound'?freq+' compounding':'Simple interest')}</div><section class="panel"><div class="panel-head"><div><h2>Your investment over time</h2><p class="sub">${m.type==='compound'?'Interest earns interest.':'Interest is earned on the original principal.'}</p></div><span class="tag">MATHEMATICAL EXAMPLE</span></div>${chart([{color:'#aebbb0',points:rows.map(r=>[r.year,m.principal])},{color:'#327655',points:rows.map(r=>[r.year,r.balance])},{color:'#b19050',points:[[selected.year,selected.balance]]}],{xLabel:x=>'Year '+x,label:'Investment balance and starting principal over time'})}<div class="legend"><span><i style="background:#327655"></i>Investment balance</span><span><i style="background:#aebbb0"></i>Starting principal</span><span><i style="background:#b19050"></i>Selected year</span></div><div class="math-inspect"><div class="between"><label for="math-inspect">Explore a year</label><strong>Year ${selected.year} · ${money(selected.balance)}</strong></div><input type="range" id="math-inspect" min="0" max="${m.years}" step="1" value="${selected.year}" aria-label="Explore a year"><div class="small">At year ${selected.year}: ${money(m.principal)} principal + ${money(selected.profit)} profit.</div></div></section><section class="panel math-formula"><div><div class="eyebrow">THE MATH BEHIND IT</div><h2>${m.solve==='rate'?(m.type==='compound'?'r = n × [(1 + G / P)^(1 / (n × t)) − 1]':'r = G / (P × t)'):(m.type==='compound'?'A = P × (1 + r / n)^(n × t)':'A = P × (1 + r × t)')}</h2><p class="small" style="margin-top:12px">P = principal · A = final amount · G = profit · r = annual rate as a decimal · t = years · n = periods per year. For quarterly/monthly compounding, r is the nominal annual rate.</p><p class="sub">${money(m.principal)} grows to ${money(last.balance)} at ${rate.toFixed(3)}% for ${m.years} years${m.type==='compound'?', compounded '+({1:'annually',4:'quarterly',12:'monthly'}[m.frequency]):''}.</p></div>${m.type==='compound'?`<div class="math-bonus"><span class="small">Extra versus simple interest</span><strong>${money(last.balance-simple)}</strong><span class="small">at the same annual rate</span></div>`:''}</section><details class="panel math-table"><summary>Year-by-year breakdown</summary><div class="table-wrap"><table><thead><tr><th>YEAR</th><th>STARTING BALANCE</th><th>INTEREST THIS YEAR</th><th>TOTAL PROFIT</th><th>ENDING BALANCE</th></tr></thead><tbody>${rows.slice(1).map((r,i)=>`<tr><td>${r.year}</td><td>${money(rows[i].balance)}</td><td>${money(r.balance-rows[i].balance)}</td><td>${money(r.profit)}</td><td><strong>${money(r.balance)}</strong></td></tr>`).join('')}</tbody></table></div></details><div class="info">${m.solve==='rate'?'The required rate is a mathematical target, not an available or promised investment return. ':''}Assumes a constant rate and no deposits, withdrawals, fees, taxes, or inflation. Market-linked products do not grow along this fixed-interest path; their separate payout rules are shown below.</div>`}
function updateMathResults(){const error=$('#math-error');if([...document.querySelectorAll('[data-math]')].some(i=>!i.checkValidity())){$('#math-results').hidden=true;return}$('#math-results').hidden=false;try{$('#math-results').innerHTML=mathResults();error.textContent='';bindMathInspect()}catch{error.textContent='Check the inputs to calculate a valid outcome.'}}
function bindMathInspect(){$('#math-inspect')?.addEventListener('input',e=>{mathModel.inspect=+e.target.value;const focused=e.target;const parent=focused.closest('.math-inspect');const selected=InvestmentMath.schedule(mathModel).rows[mathModel.inspect];parent.querySelector('strong').textContent=`Year ${selected.year} · ${money(selected.balance)}`;parent.querySelector('.small').textContent=`At year ${selected.year}: ${money(mathModel.principal)} principal + ${money(selected.profit)} profit.`;const svg=$('#math-results .chart');const w=700,h=260,left=62,right=24,top=22,bottom=36;const {rows}=InvestmentMath.schedule(mathModel),lo=Math.min(mathModel.principal,...rows.map(r=>r.balance))*.85,hi=Math.max(mathModel.principal,...rows.map(r=>r.balance))*1.08;const x=left+mathModel.inspect/mathModel.years*(w-left-right),y=h-bottom-(selected.balance-lo)/(hi-lo)*(h-top-bottom);const circle=svg.querySelector('circle:last-of-type'),path=svg.querySelector('path:last-of-type');circle.setAttribute('cx',x);circle.setAttribute('cy',y);circle.querySelector('title').textContent=`Year ${selected.year}: ${money(selected.balance)}`;path.setAttribute('d',`M${x},${y}`)})}
function bindMath(){if(tab!=='scenarios')return;document.querySelectorAll('[data-math]').forEach(input=>input.addEventListener('input',()=>{if(!input.checkValidity()){ $('#math-results').hidden=true;$('#math-error').textContent=`Enter ${input.getAttribute('aria-label').toLowerCase()} between ${input.min} and ${input.max}, in steps of ${input.step}.`;return}mathModel[input.dataset.math]=Number(input.value);mathModel.inspect=Math.min(mathModel.inspect,mathModel.years);document.querySelector(`[data-math-range="${input.dataset.math}"]`).value=input.value;updateMathResults()}));document.querySelectorAll('[data-math-range]').forEach(input=>input.addEventListener('input',()=>{mathModel[input.dataset.mathRange]=+input.value;mathModel.inspect=Math.min(mathModel.inspect,mathModel.years);document.querySelector(`[data-math="${input.dataset.mathRange}"]`).value=input.value;updateMathResults()}));$('#math-solve').onchange=e=>{const result=InvestmentMath.schedule(mathModel);if(e.target.value==='rate')mathModel.profit=Math.round(result.rows.at(-1).profit*100)/100;else mathModel.rate=Math.round(result.rate*100)/100;mathModel.solve=e.target.value;render()};$('#math-type').onchange=e=>{mathModel.type=e.target.value;render()};if($('#math-frequency'))$('#math-frequency').onchange=e=>{mathModel.frequency=+e.target.value;updateMathResults()};$('#math-reset').onclick=()=>{seedMath();render();toast('Calculator reset from your saved plan')};bindMathInspect()}
function dynamicProductChart(){return chart([{color:'#3b7f5e',points:Array.from({length:21},(_,i)=>{let r=-100+i*10;return [r,E.payoff(state,r)]})},...['down','flat','up'].map((key,i)=>({color:['#c19a61','#a2b795','#4f8967'][i],points:[[state[key],E.payoff(state,state[key])]]}))],{target:state.target,xLabel:x=>x+'%',label:'Product maturity payout with live market scenario markers'})}
function dynamicProductChartHTML(){return `<div id="product-payoff-chart">${dynamicProductChart()}</div>`}
